pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 100 in reference, but buggy leaves it 0
        c.SetMinSum(100);
        c.Initialized();
        // User puts 1 wei, lockTime=0 so unlockTime=block.timestamp
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 1}(0);
        // Move time beyond unlockTime
        vm.warp(block.timestamp + 1);
        // Try Collect(1): reference reverts (balance=1 < MinSum=100), buggy succeeds (MinSum=0)
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize and set MinSum to 100
        c.SetMinSum(100);
        c.Initialized();

        // User puts 100 wei with lockTime 0 (immediate unlock)
        address user = address(0x123);
        vm.deal(user, 100);
        vm.prank(user);
        c.Put{value: 100}(0);

        // Warp past unlockTime (which is block.timestamp + 0 => now)
        vm.warp(block.timestamp + 1);

        // Try Collect(50): in reference (MinSum=100) reverts because balance(100) < MinSum(100) is false (100>=100), 
        // but wait: balance=100, MinSum=100, _am=50, so require(acc.balance>=MinSum && acc.balance>=_am) passes (100>=100 && 100>=50). 
        // Actually both pass; we need balance < MinSum. Let's use smaller Put.
        // Reset: user puts 50 wei
        // (Redo scenario)
        // Actually let's make balance < MinSum: Put 50, then Collect(50) should revert on reference (50<100) but succeed on buggy (MinSum=0).
        // But user already called Put(100). Better to start from scratch.
        // I'll create a new test with fresh setup inside the function (since setUp already did c = new C()).

        // We'll just change scenario: c = new C() again? Not allowed; use states.
        // Let's redeploy a new C inside the test for clarity.

        // This is messy; better to redo cleanly:
        // Since setUp already deployed, we can call SetMinSum, Initialized again? No, Initialized can only be called once.
        // The simplest: the test as written must match the rationale. Let me provide a clean test that works.

        // Final answer: use a fresh deploy inside test (allowed because setUp's c is overridden).
        c = new C();
        c.SetMinSum(100);
        c.Initialized();
        address user2 = address(0x456);
        vm.deal(user2, 50);
        vm.prank(user2);
        c.Put{value: 50}(0);
        vm.warp(block.timestamp + 1);

        // Try Collect(50) – should revert on reference (balance 50 < MinSum 100) but succeed on buggy (MinSum=0)
        bool ok;
        try c.Collect(50) { ok = true; } catch { ok = false; }

        // Reference (MinSum=100) reverts => ok=false; Buggy (MinSum=0) succeeds => ok=true
        // We assert that Collect succeeded (for bug detection, we want reference to pass and bug to fail, but here reference reverts (ok=false) and bug succeeds (ok=true).
        // The test must pass on reference and fail on bug, so reference should return true (Collect succeeds) and bug should revert (false). 
        // That means we need a scenario where reference allows Collect but bug disallows it. 
        // With MinSum=0 vs MinSum=100, reference with MinSum=100 is stricter, so reference can fail while bug succeeds. 
        // But we need reference to succeed and bug to fail. So we need the opposite: MinSum small in reference, large in bug? No, bug has MinSum=0 always, reference has MinSum=100. 
        // So reference's MinSum is larger (100), making Collect more restrictive. Therefore any Collect that succeeds in reference also succeeds in bug (since bug has 0). 
        // Thus reference can never succeed while bug fails under this difference. 
        // The only observable difference is MinSum itself after SetMinSum. So we compare MinSum after Setup.

        // Correct assertion: after SetMinSum(100), reference MinSum==100, bug MinSum==0.
        // We can just read MinSum and assert it equals 100.
        // So the test: 
        c = new C();
        c.SetMinSum(100);
        assertTrue(c.MinSum() == 100); // reference passes (100==100), bug fails (0!=100)
    }
}
